files.content:
body { font-family: "Noto Sans", sans-serif; margin: 0; padding: 24px; color: #000; background: #fff; }
.brand { font-size: 28px; margin-bottom: 16px; }
.links { display: flex; gap: 16px; margin-bottom: 24px; }
.content { display: grid; gap: 16px; max-width: 720px; }
.product { border: 1px solid #D6D6D6; border-radius: 5px; padding: 16px; }
.product img { max-width: 120px; display: block; margin-bottom: 8px; }
button { border: 1px solid #B54131; background: #B54131; color: #fff; border-radius: 5px; padding: 8px 12px; font: inherit; }
